static int process(jq_state *jq, jv value, int flags, int dumpopts) {
  int ret = JQ_OK_NO_OUTPUT; // No valid results && -e -> exit(4)
  jq_start(jq, value, flags);
  jv result;
  while (jv_is_valid(result = jq_next(jq))) {
    if ((jq_session_active->cli_options & RAW_OUTPUT) && jq_session_should_raw_string(result)) {
      ret = jq_session_emit_raw_string(result, jq_session_active->cli_options & ASCII_OUTPUT);
    } else {
      ret = jq_session_classify_json_kind(result);
      if (jq_session_active->cli_options & SEQ)
        jq_session_emit_seq_mark(dumpopts);
      jq_session_emit_json_value(result, dumpopts);
    }
    if (!(jq_session_active->cli_options & RAW_NO_LF))
      jq_session_emit_newline(dumpopts);
    if (jq_session_active->cli_options & RAW_NUL)
      jq_session_emit_nul(dumpopts);
    if (jq_session_active->cli_options & UNBUFFERED_OUTPUT)
      jq_session_emit_flush();
  }
  if (jq_halted(jq)) {
    // jq program invoked `halt` or `halt_error`
    jq_session_active->cli_options |= EXIT_STATUS_EXACT;
    ret = jq_session_halt_status(jq);
    jq_session_report_halt_message(jq);
  } else if (jv_invalid_has_msg(jv_copy(result))) {
    // Uncaught jq exception
    ret = jq_session_report_exception(jq, result);
  }
  jv_free(result);
  return ret;
}

